package com.bank.dispenser.service;

import java.util.logging.Logger;

// Counts distinct combinations of note denominations forming an amount (unbounded).
public class DispenserCombinationService {
    private static final Logger log = Logger.getLogger(DispenserCombinationService.class.getName());

    public long countWays(int[] denominations, int amount) {
        long[] dp = new long[amount + 1];
        dp[0] = 1;                                  // one way to make 0: no notes
        // Coins OUTER, amounts INNER ⇒ count combinations, not permutations.
        for (int note : denominations) {
            for (int a = note; a <= amount; a++) {
                dp[a] += dp[a - note];
            }
        }
        log.info(() -> "Ways to make " + amount + " = " + dp[amount]);
        return dp[amount];
    }
}
