package com.bank.dispenser;

import com.bank.dispenser.service.DispenserCombinationService;
import java.util.logging.Logger;

public class DispenserCombinationApplication {
    private static final Logger log = Logger.getLogger(DispenserCombinationApplication.class.getName());

    public static void main(String[] args) {
        DispenserCombinationService service = new DispenserCombinationService();
        int[] notes = {1, 2, 5};        // note denominations (hundreds)
        int amount = 5;
        long ways = service.countWays(notes, amount);
        log.info("Distinct ways to dispense " + amount + ": " + ways);
    }
}
